CREATE OR REPLACE FUNCTION public.claim_job_quick_read_auto(p_job_id text, p_formatter text, p_token uuid, p_source_rules text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 a public.quick_read_auto_queue%rowtype;
 c public.quick_read_rollout_stop%rowtype;
 result jsonb;
begin
 if p_token is null or p_job_id is null or p_job_id!~'^[1-9][0-9]{0,18}$' then
   return jsonb_build_object('status','invalid');
 end if;
 -- Preserve global gate before rollout, queue, and cache locks.
 perform 1 from public.quick_read_control where id for update;
 select * into c from public.quick_read_rollout_stop where id for update;
 if not found or not c.enabled then
   return jsonb_build_object('status','rollout_disabled');
 end if;
 if c.cooldown_until>now() then return jsonb_build_object('status','credit_paused'); end if;
 if not c.ongoing and c.claims>=293 then return jsonb_build_object('status','rollout_exhausted'); end if;
 if not c.ongoing and (c.worst_request_usd<=0 or c.reserved_usd+c.worst_request_usd>c.budget_usd) then
   return jsonb_build_object('status','spending_stopped');
 end if;

 if not exists(select 1 from public.quick_read_auto_control where id and enabled and activated_at is not null)
 then return jsonb_build_object('status','disabled'); end if;
 select * into a from public.quick_read_auto_queue where job_id=p_job_id for update;
 if not found or a.state not in ('pending','running') or a.attempts>=3 or a.next_attempt_at>now()
 or a.inserted_at<(select activated_at from public.quick_read_auto_control where id)
 then return jsonb_build_object('status','not_due'); end if;
 -- Preserve the existing per-job retry limit and previous-manual-attempt check.
 if not a.recovery and exists(select 1 from public.job_quick_reads where job_id=p_job_id and (a.attempts=0 or updated_at>a.updated_at)) then
   update public.quick_read_auto_queue set state='stopped',last_status='previously_attempted',updated_at=now() where job_id=p_job_id;
   return jsonb_build_object('status','previously_attempted');
 end if;
 result:=public.claim_job_quick_read_recovery(p_job_id,p_formatter,p_token,p_source_rules);
 if result->>'status'='claimed' then
   update public.quick_read_auto_queue set state='running',attempts=attempts+1,claim_token=p_token,
    next_attempt_at=now()+interval '1 hour'*power(2,a.attempts),last_status='claimed',updated_at=now() where job_id=p_job_id;
   -- Same transaction as the claim; retain the worst-case reservation after crashes.
   update public.quick_read_rollout_stop set claims=claims+1,
    reserved_usd=reserved_usd+worst_request_usd,
    enabled=(ongoing or (claims+1<293 and reserved_usd+2*worst_request_usd<=budget_usd)) where id;
 elsif result->>'status' in ('unchanged','unsupported','invalid') then
   update public.quick_read_auto_queue set state='stopped',last_status=result->>'status',updated_at=now() where job_id=p_job_id;
 else
   update public.quick_read_auto_queue set next_attempt_at=now()+interval '5 minutes',updated_at=now() where job_id=p_job_id;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.claim_job_quick_read_recovery(p_job_id text, p_formatter text, p_token uuid, p_source_rules text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare source text; fingerprint text; cached public.job_quick_reads%rowtype; gate timestamptz;
begin
 if p_source_rules is null or p_source_rules!~'^[a-z0-9-]{1,64}$' then return jsonb_build_object('status','invalid'); end if;
 if p_formatter<>'source-organizer-v2' or p_job_id!~'^[1-9][0-9]{0,18}$' then return jsonb_build_object('status','invalid'); end if;
 -- A global serialized rate gate also protects concurrent manual/batch callers.
 select next_claim_at into gate from public.quick_read_control where id=true for update;
 select j.description into source from public.jobs j where j.id::text=p_job_id
   and j.status='active' and j.philippines_eligible is true
   and exists(select 1 from public.public_jobs v where v.id=j.id);
 if source is null or length(btrim(source))<100 or length(source)>40000 then return jsonb_build_object('status','ineligible'); end if;
 fingerprint:=encode(extensions.digest(convert_to(source,'UTF8'),'sha256'),'hex');
 select * into cached from public.job_quick_reads where job_id=p_job_id for update;
 if found then
   if cached.status='running' and cached.lease_until>now() then return jsonb_build_object('status','busy'); end if;
   if cached.source_hash=fingerprint and cached.formatter_version=p_formatter then
     if cached.status='failed' and cached.error_code in ('unsupported_source','unsafe_source') and (cached.source_rules_version is null or cached.source_rules_version=p_source_rules) then return jsonb_build_object('status','unsupported'); end if;
     if cached.status='ready' and cached.schema_version=2 then return jsonb_build_object('status','unchanged'); end if;
     if cached.status='failed' and cached.retry_after>now() and (cached.error_code not in ('unsupported_source','unsafe_source') or cached.source_rules_version is null or cached.source_rules_version=p_source_rules) then return jsonb_build_object('status','retry_later'); end if;
   end if;
 end if;
 if gate>now() then return jsonb_build_object('status','rate_limited'); end if;
 update public.quick_read_control set next_claim_at=now()+interval '10 seconds' where id=true;
 insert into public.job_quick_reads(job_id,source_hash,formatter_version,status,claim_token,lease_until,source_rules_version)
 values(p_job_id,fingerprint,p_formatter,'running',p_token,now()+interval '3 minutes',p_source_rules)
 on conflict(job_id) do update set source_hash=excluded.source_hash,formatter_version=excluded.formatter_version,
 status='running',claim_token=excluded.claim_token,lease_until=excluded.lease_until,payload=null,error_code=null,failure_diagnostics=null,source_rules_version=p_source_rules,updated_at=now();
 return jsonb_build_object('status','claimed','description',source,'source_hash',fingerprint);
end $function$

CREATE OR REPLACE FUNCTION public.finish_job_quick_read_auto(p_job_id text, p_token uuid, p_payload jsonb, p_model text, p_schema integer, p_error text, p_diagnostics jsonb, p_source_rules text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result jsonb; retryable boolean;
begin
 perform 1 from public.quick_read_control where id for update;
 if not exists(select 1 from public.quick_read_auto_queue where job_id=p_job_id and state='running' and claim_token=p_token)
 then return jsonb_build_object('status','claim_expired'); end if;
 result:=public.finish_job_quick_read_with_diagnostics(p_job_id,p_token,p_payload,p_model,p_schema,p_error,p_diagnostics,p_source_rules);
 if result->>'status'='failed' and p_error in ('provider_insufficient_credit','provider_http_429','provider_http_401','provider_http_403') then
   update public.quick_read_rollout_stop set cooldown_until=now()+case when p_error='provider_http_429' then interval '1 minute' else interval '15 minutes' end,pause_reason=p_error where id;
   update public.job_quick_reads set retry_after=now()+case when p_error='provider_http_429' then interval '1 minute' else interval '15 minutes' end where job_id=p_job_id and status='failed';
   update public.quick_read_auto_queue set state='pending',attempts=greatest(0,attempts-1),claim_token=null,
     next_attempt_at=now()+case when p_error='provider_http_429' then interval '1 minute' else interval '15 minutes' end,last_status=p_error,updated_at=now() where job_id=p_job_id and claim_token=p_token;
   return result;
 end if;
 if result->>'status'='ready' then update public.quick_read_rollout_stop set cooldown_until=null,pause_reason=null where id; end if;
 retryable:=coalesce(p_error='generation_failed' or p_error='provider_http_429' or p_error ~ '^provider_http_5[0-9]{2}$',false);
 update public.quick_read_auto_queue set
 state=case when result->>'status'='ready' then 'done'
   when result->>'status'='failed' and retryable and attempts<3 then 'pending' else 'stopped' end,
 claim_token=null,last_status=case when result->>'status'='failed' then left(p_error,100) else result->>'status' end,
 updated_at=now() where job_id=p_job_id and claim_token=p_token;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.finish_job_quick_read(p_job_id text, p_token uuid, p_payload jsonb, p_model text, p_schema integer, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare cached public.job_quick_reads%rowtype; fingerprint text;
begin
 select * into cached from public.job_quick_reads where job_id=p_job_id for update;
 if not found or cached.status<>'running' or cached.claim_token is distinct from p_token or cached.lease_until<now() then return jsonb_build_object('status','claim_expired'); end if;
 select encode(extensions.digest(convert_to(j.description,'UTF8'),'sha256'),'hex') into fingerprint
 from public.jobs j where j.id::text=p_job_id and j.status='active' and j.philippines_eligible is true
 and exists(select 1 from public.public_jobs v where v.id=j.id);
 if fingerprint is distinct from cached.source_hash then
   update public.job_quick_reads set status='failed',payload=null,error_code='source_changed',retry_after=now(),claim_token=null,lease_until=null,updated_at=now() where job_id=p_job_id;
   return jsonb_build_object('status','source_changed');
 end if;
 if p_error is null and (p_schema<>2 or p_schema is null or p_payload is null or jsonb_typeof(p_payload)<>'object'
   or p_payload->>'formatter'<>'source-organizer-v2' or p_payload->>'version'<>'2') then raise exception 'Invalid payload'; end if;
 update public.job_quick_reads set status=case when p_error is null then 'ready' else 'failed' end,
   payload=case when p_error is null then p_payload else null end,model=left(p_model,100),schema_version=p_schema,
   error_code=left(p_error,100),generated_at=case when p_error is null then now() else null end,
   retry_after=case when p_error is null then null else now()+interval '1 hour' end,
   claim_token=null,lease_until=null,updated_at=now() where job_id=p_job_id;
 return jsonb_build_object('status',case when p_error is null then 'ready' else 'failed' end);
end $function$

CREATE OR REPLACE FUNCTION public.finish_job_quick_read_with_diagnostics(p_job_id text, p_token uuid, p_payload jsonb, p_model text, p_schema integer, p_error text, p_diagnostics jsonb, p_source_rules text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare result jsonb;
begin
 if p_source_rules is null or p_source_rules!~'^[a-z0-9-]{1,64}$' or not public.quick_read_valid_diagnostics(p_diagnostics) then raise exception 'Invalid diagnostic metadata'; end if;
 -- Existing finish keeps the row locked through this transaction and checks the
 -- claim token, lease, visibility and source revision before saving anything.
 result:=public.finish_job_quick_read(p_job_id,p_token,p_payload,p_model,p_schema,p_error);
 if result->>'status' in ('ready','failed') then
   update public.job_quick_reads set failure_diagnostics=case when result->>'status'='failed' then p_diagnostics else null end,
     source_rules_version=p_source_rules,
     retry_after=case when result->>'status'='failed' and p_error in ('unsupported_source','unsafe_source') then 'infinity'::timestamptz else retry_after end
   where job_id=p_job_id;
 end if;
 return result;
end $function$
